// Reservations
let editingReservationId=null,reservationEditSequence=0,reservationSaving=false;
function resetReservationMode(){
 editingReservationId=null;reservationEditSequence++;
 const title=$('#modalReservation .modal-title'),button=$('#formReservation button[type="submit"]');
 if(title)title.textContent='Nouvelle réservation (hôtel inclus)';if(button)button.textContent='Réserver';
}
async function editReservation(id){
 if(!canDeleteReservation()||reservationSaving)return;
 const seq=++reservationEditSequence,eventId=currentEventId;
 try{
  const data=await apiFetch('/reservations/'+encodeURIComponent(id));
  if(seq!==reservationEditSequence||String(eventId)!==String(currentEventId))return;
  if(String(data.event_id)!==String(eventId))throw new Error('Réservation hors de cet événement');
  const form=$('#formReservation');
  bootstrap.Modal.getOrCreateInstance($('#modalReservation')).show();
  editingReservationId=data.id;
  for(const name of ['hotel_nom','hotel_wilaya_id','hotel_adresse','hotel_telephone','hotel_email','type_chambre','numero_chambre','capacite_max','prix_nuit','nb_nuits','statut','date_arrivee','date_depart','notes']){
   if(form.elements[name])form.elements[name].value=name.startsWith('date_')?String(data[name]||'').slice(0,10):(data[name]??'');
  }
  window.ReservationOccupants?.set((data.occupants||[]).map(p=>({...p,key:p.source+':'+(p.source==='equipe'?p.employe_id:p.source==='intervenants'?p.intervenant_id:p.personne_id)})));
  $('#modalReservation .modal-title').textContent='Modifier la réservation';
  $('#formReservation button[type="submit"]').textContent='Enregistrer les modifications';
 }catch(err){toast(err.message||'Chargement impossible','danger');}
}
const reservationDeletes=new Set();
function canDeleteReservation(){
 return !!currentUser&&!isViewer()&&!!(isPrivilegedRole(currentUser.role)||currentUser.permissions?.all||currentUser.permissions?.reservations);
}
async function deleteReservation(id){
 if(!canDeleteReservation()||!Number.isInteger(Number(id))||Number(id)<=0||reservationDeletes.has(String(id)))return;
 if(!confirm('Supprimer cette réservation d’hôtel ? Cette action est irréversible. Les fiches des occupants seront conservées.'))return;
 reservationDeletes.add(String(id));
 try{
  await apiFetch('/reservations/'+encodeURIComponent(id),{method:'DELETE'});
  toast('Réservation supprimée');
  await loadReservations();
  await loadHotelAlerts();
 }catch(err){toast(err.message||'Suppression de la réservation impossible','danger');}
 finally{reservationDeletes.delete(String(id));}
}
async function loadReservations(){
 if(!currentEventId)return;
 const body=$('#reservationsTableBody');if(!body)return;
 try{
  const rows=await apiFetch(`/reservations/event/${currentEventId}`);
  body.innerHTML=rows.length?rows.map(r=>`<tr>
   <td>${escHtml(r.hotel_nom||'—')}${r.wilaya_nom?` (${escHtml(r.wilaya_nom)})`:''}<br>Ch ${escHtml(r.numero_chambre||'—')} ${escHtml(r.type_chambre||'')} cap ${Number(r.capacite_max)||0}</td>
   <td>${escHtml(r.date_arrivee||'—')} → ${escHtml(r.date_depart||'—')}<br>${Number(r.nb_nuits)||0} nuits × ${money(r.prix_nuit)} = ${money(Number(r.prix_nuit||0)*Number(r.nb_nuits||0))}</td>
   <td>${Number(r.nb_occupants)||0}/${Number(r.capacite_max)||0} occupants</td>
   <td><span class="badge bg-${r.statut==='confirmee'?'success':'warning'}">${escHtml(r.statut||'—')}</span></td>
   <td class="text-end">${canDeleteReservation()?`<div class="d-flex gap-2 justify-content-end"><button type="button" class="btn btn-sm btn-outline-primary" title="Modifier la réservation" aria-label="Modifier la réservation" onclick="event.stopPropagation();editReservation(${Number(r.id)})"><i class="bi bi-pencil" aria-hidden="true"></i></button><button type="button" class="btn btn-sm btn-outline-danger" title="Supprimer la réservation" aria-label="Supprimer la réservation" ${reservationDeletes.has(String(r.id))?'disabled':''} onclick="event.stopPropagation();deleteReservation(${Number(r.id)})"><i class="bi bi-trash" aria-hidden="true"></i></button></div>`:''}</td>
  </tr>`).join(''):'<tr><td colspan="5" class="text-center text-muted py-4">Aucune réservation enregistrée.</td></tr>';
 }catch(err){body.innerHTML='<tr><td colspan="5" class="text-center text-danger py-4">Impossible de charger les réservations.</td></tr>';toast(err.message,'danger');}
}

