// CRUD helpers
const SECTION_META = {
  dashboard:   { t:'Tableau de bord',s:'Votre événement en un regard'},
  events:      { t:'Accueil · Mes Événements'},
  stands:      { t:'Stands & Plan'},
  personnes:   { t:'Participants'},
  exposants:   { t:'Exposants'},
  equipe:      { t:'Équipe'},
  intervenants:{ t:'Intervenants'},
  autorisations:{ t:'Autorisations'},
  documents:   { t:'Documents de l\'événement'},
  finances:    { t:'Gestion des finances'},
  sponsors:    { t:'Sponsors'},
  restauration:{ t:'Restauration'},
  conventions: { t:'Conventions'},
  billets:     { t:'Billets d\'Avion'},
  reservations:{ t:'Réservations Hôtel'},
  programmes:  { t:'Programme'},
  users:       { t:'Utilisateurs & Permissions'},
  audit:       { t:'Journal d\'Audit'}
};
function showSection(id){
  if(currentUser && !allowedSections().has(id)){
    toast('Rubrique non accessible avec ce compte','danger');
    return;
  }
  if(id==='users' && !canManageUsers()){
    toast('Accès réservé aux administrateurs','danger');
    return;
  }
  // Mode accueil : sidebar masquée tant qu'aucun événement n'est entré
  const wrapper = $('#appWrapper');
  if(wrapper) wrapper.classList.toggle('home-mode', id==='events');
  if(!['events','users','audit'].includes(id) && !currentEventId){
    toast('Sélectionnez d\'abord un événement (barre du haut) pour ajouter des données','warning');
  }
  $$('.content-section').forEach(s=>s.classList.add('d-none'));
  $('#section-'+id).classList.remove('d-none');
  $$('.sidebar .nav-link').forEach(l=>l.classList.remove('active'));
  const active = $(`.sidebar .nav-link[data-section="${id}"]`);
  if(active) active.classList.add('active');
  const meta = SECTION_META[id];
  if(meta){
    const pt = $('#pageTitle'); if(pt) pt.textContent = meta.t;
    const ps = $('#pageSubtitle'); if(ps) ps.textContent = meta.s;
  }
  if(id==='users') loadUsers();
  if(id==='events') loadHomeEvents();
  if(id==='equipe') loadEquipe();
  if(id==='intervenants') loadIntervenants();
  if(id==='autorisations') loadAutorisations();
  if(id==='documents') loadDocuments();
  if(id==='finances') loadFinances();
  if(id==='billets') loadBillets();
  if(id==='reservations') loadReservations();
  if(window.innerWidth<1100) $('.sidebar').classList.remove('show');
  document.dispatchEvent(new CustomEvent('app:section',{detail:{id}}));
}
