function escHtml(v){ return String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])); }
function fileUrl(v){ return v ? (String(v).startsWith('/') ? String(v) : '/'+String(v)) : ''; }
function profilePhoto(v, label=''){
  return v ? `<img class="avatar-sm avatar-photo" src="${escHtml(fileUrl(v))}" alt="${escHtml(label)}">` : `<span class="avatar-sm">${escHtml(initialsOf(label))}</span>`;
}
function money(v){ return Number(v||0).toLocaleString('fr-FR')+' DA'; }

let equipeActiveCategoryId='';
let equipeActiveEventId=null;
let equipeCategoriesCache=[];
let equipeProfilesCache=[];
let editingEquipeId=null;

function showEquipeCategories(){
  equipeActiveCategoryId='';
  $('#equipeCategoriesView')?.classList.remove('d-none');
  $('#equipeProfilesView')?.classList.add('d-none');
}
async function loadEquipe(){
  if(!currentEventId) return;
  if(String(equipeActiveEventId)!==String(currentEventId)){
    equipeActiveEventId=currentEventId;
    equipeActiveCategoryId='';
  }
  try{
    equipeCategoriesCache=await apiFetch(`/equipe/event/${currentEventId}/categories`);
    const cards=$('#equipeCategories');
    if(cards){
      cards.innerHTML=equipeCategoriesCache.map(c=>`<div class="col-6 col-md-4 col-xl-3"><div class="team-category-frame"><button class="team-category-card" style="--team-color:${escHtml(c.couleur||'#2f6bff')}" onclick="loadEquipeProfiles(${c.id})"><span class="team-category-icon"><i class="bi bi-people"></i></span><span class="team-category-name">${escHtml(c.nom)}</span><span class="team-category-count">${c.nb_profiles||0} profil(s)</span></button>${!isViewer()?`<button type="button" class="btn category-delete" onclick="deleteEquipeCategory(${c.id})" aria-label="Supprimer la catégorie ${escHtml(c.nom)}"><i class="bi bi-trash" aria-hidden="true"></i></button>`:''}</div></div>`).join('')+`<div class="col-6 col-md-4 col-xl-3"><button class="team-category-card team-category-add" onclick="addEquipeCategory()"><span class="team-category-icon"><i class="bi bi-plus-lg"></i></span><span class="team-category-name">Ajouter une catégorie</span><span class="team-category-count">Personnalisée</span></button></div>`;
    }
    const sel=$('#equipeCategoryFilter');
    if(sel) sel.innerHTML='<option value="">Toutes les catégories</option>'+equipeCategoriesCache.map(c=>`<option value="${c.id}">${escHtml(c.nom)} (${c.nb_profiles||0})</option>`).join('');
    const modalSel=$('#equipeCategorySelect');
    if(modalSel && !editingEquipeId) modalSel.innerHTML='<option value="">-- Choisir une catégorie --</option>'+equipeCategoriesCache.map(c=>`<option value="${c.id}">${escHtml(c.nom)}</option>`).join('');
    if(equipeActiveCategoryId && equipeCategoriesCache.some(c=>String(c.id)===String(equipeActiveCategoryId))) await loadEquipeProfiles(equipeActiveCategoryId);
    else showEquipeCategories();
  }catch(e){ console.error(e); }
}
async function loadEquipeProfiles(categoryId=''){
  if(!currentEventId) return;
  if(!categoryId){showEquipeCategories();return;}
  equipeActiveCategoryId=String(categoryId);
  $('#equipeCategoriesView')?.classList.add('d-none');
  $('#equipeProfilesView')?.classList.remove('d-none');
  $('#equipeProfilesBody').innerHTML='<tr><td colspan="8" class="text-center py-4">Chargement…</td></tr>';
  try{
    const url=categoryId?`/equipe/event/${currentEventId}?category_id=${encodeURIComponent(categoryId)}`:`/equipe/event/${currentEventId}`;
    equipeProfilesCache=await apiFetch(url);
    const cat=equipeCategoriesCache.find(c=>String(c.id)===String(categoryId));
    if($('#equipeListTitle')) $('#equipeListTitle').textContent=cat?`Profils · ${cat.nom}`:'Tous les profils';
    const body=$('#equipeProfilesBody'); if(!body) return;
    body.innerHTML=equipeProfilesCache.length?equipeProfilesCache.map(p=>{
      const label=`${p.nom} ${p.prenom}`;
      return `<tr class="clickable-row" onclick="if(!event.target.closest('button,a,input'))editEquipe(${p.id})"><td><div class="d-flex align-items-center gap-2">${profilePhoto(p.photo_path,label)}<div><b>${escHtml(label)}</b><br><small>${escHtml(p.email||'')}</small></div></div></td><td><span class="badge" style="background:${escHtml(p.categorie_couleur||'#2f6bff')}">${escHtml(p.categorie_nom||p.poste||'Équipe')}</span></td><td>${escHtml(p.responsable||'—')}</td><td>${escHtml(p.telephone||'—')}</td><td>${money(p.salaire_jour)} × ${p.nb_jours||1}</td><td><b>${money(p.salaire_total||Number(p.salaire_jour||0)*Number(p.nb_jours||1))}</b></td><td><span class="badge bg-${p.statut_paiement==='paye'?'success':p.statut_paiement==='partiel'?'warning':'secondary'}">${escHtml(p.statut_paiement||'non_paye')}</span></td><td><button class="btn btn-sm btn-outline-secondary" onclick="editEquipe(${p.id})"><i class="bi bi-pencil"></i></button> <button class="btn btn-sm btn-outline-danger" onclick="deleteEquipe(${p.id})"><i class="bi bi-trash"></i></button></td></tr>`;
    }).join(''):'<tr><td colspan="8" class="text-center text-muted py-4">Aucun profil dans cette catégorie.</td></tr>';
  }catch(e){ $('#equipeProfilesBody').innerHTML='<tr><td colspan="8" class="text-center text-danger py-4">Impossible de charger les employés. Revenez aux catégories puis réessayez.</td></tr>';toast(e.message,'danger'); }
}
const equipeCategoryDeletes=new Set();
async function deleteEquipeCategory(id){
  if(isViewer()||equipeCategoryDeletes.has(String(id)))return;
  const category=equipeCategoriesCache.find(c=>String(c.id)===String(id));
  if(!category)return;
  if(Number(category.nb_profiles)>0){toast('Déplacez ou supprimez les profils de cette catégorie avant de la supprimer.','warning');return;}
  if(!confirm(`Supprimer la catégorie « ${category.nom} » ?`))return;
  equipeCategoryDeletes.add(String(id));
  try{
    await apiFetch(`/equipe/categories/${encodeURIComponent(id)}`,{method:'DELETE'});
    if(String(equipeActiveCategoryId)===String(id))equipeActiveCategoryId='';
    toast('Catégorie supprimée');
    await loadEquipe();
  }catch(e){toast(e.message,'danger');}
  finally{equipeCategoryDeletes.delete(String(id));}
}
async function addEquipeCategory(){
  const nom=prompt('Nom de la nouvelle catégorie (ex. Décoration)');
  if(!nom||!nom.trim()) return;
  try{ await apiFetch('/equipe/categories',{method:'POST',body:{event_id:currentEventId,nom:nom.trim()}}); toast('Catégorie ajoutée'); loadEquipe(); }catch(e){toast(e.message,'danger');}
}
