async function loadFinances(){
  if(!currentEventId)return;try{const [summary,transactions]=await Promise.all([apiFetch(`/finances/event/${currentEventId}/summary`),apiFetch(`/finances/event/${currentEventId}/transactions`)]);const t=summary.totals||{};$('#financesTotalEntrants').textContent=money(t.entrants);$('#financesTotalSortants').textContent=money(t.sortants);const bal=$('#financesBalance');bal.textContent=(Number(t.balance)>=0?'+':'−')+money(Math.abs(Number(t.balance||0)));bal.classList.toggle('text-danger',Number(t.balance)<0);bal.classList.toggle('text-success',Number(t.balance)>=0);const a=summary.automatic||{entrants:{},sortants:{}};const incoming=[['Budget initial',a.entrants.budget_initial],['Exposants',a.entrants.exposants],['Sponsors',a.entrants.sponsors]];const outgoing=[['Équipe',a.sortants.equipe],['Billets',a.sortants.billets],['Hôtels',a.sortants.hotels],['Conventions',a.sortants.conventions],['Restauration',a.sortants.restauration]];$('#financesAutoBody').innerHTML=Array.from({length:Math.max(incoming.length,outgoing.length)},(_,n)=>`<tr><td>${incoming[n]?escHtml(incoming[n][0]):''}</td><td class="text-success">${incoming[n]?money(incoming[n][1]):''}</td><td>${outgoing[n]?escHtml(outgoing[n][0]):''}</td><td class="text-danger">${outgoing[n]?money(outgoing[n][1]):''}</td></tr>`).join('');$('#financesTransactionsBody').innerHTML=transactions.length?transactions.map(x=>`<tr><td>${fmtDate(x.date_transaction)}</td><td><span class="badge bg-${x.type==='entrant'?'success':'danger'}">${x.type==='entrant'?'Entrée':'Sortie'}</span></td><td>${escHtml(x.categorie||'')}</td><td>${escHtml(x.libelle)}</td><td>${money(x.montant)}</td><td><button class="btn btn-sm btn-outline-danger" onclick="deleteTransaction(${x.id})"><i class="bi bi-trash"></i></button></td></tr>`).join(''):'<tr><td colspan="6" class="text-center text-muted py-4">Aucune transaction manuelle.</td></tr>';}catch(e){toast(e.message,'danger');}
}
