(function(){
 if(window.__ea26_refinements)return;window.__ea26_refinements=true;
 const labels={jour:'Jour',heure_debut:'Heure de début',heure_fin:'Heure de fin',ordre:'Ordre',nom:'Nom',prenom:'Prénom',email:'Email',telephone:'Téléphone',poste:'Fonction',entreprise:'Entreprise',wilaya_id:'Wilaya',nin:'NIN',categorie_id:'Catégorie',responsable:'Responsable',salaire_jour:'Tarif par jour (DA)',nb_jours:'Nombre de jours',date_debut:'Date de début',date_fin:'Date de fin',statut_paiement:'Paiement',photo:'Photo',engagement:'Engagement',presentation:'Présentation',presentation_file:'Présentation',titre:'Titre',description:'Description',notes:'Notes',type:'Type',theme:'Thème',salle:'Salle',hotel_nom:'Nom de l’hôtel',hotel_wilaya_id:'Wilaya de l’hôtel',hotel_adresse:'Adresse de l’hôtel',hotel_telephone:'Téléphone de l’hôtel',hotel_email:'Email de l’hôtel',type_chambre:'Type de chambre',numero_chambre:'N° de chambre',capacite_max:'Capacité maximale',prix_nuit:'Prix par nuit (DA)',nb_nuits:'Nombre de nuits',date_arrivee:'Date et heure d’arrivée',date_depart:'Date et heure de départ',statut:'Statut de réservation',contact_nom:'Nom du contact',contact_email:'Email du contact',contact_tel:'Téléphone du contact',logo:'Logo',montant:'Montant (DA)',avantages:'Avantages',organisme:'Organisme',date_demande:'Date de demande',date_obtention:'Date d’obtention',fichier:'Fichier',convention_doc:'Documents PDF / Word',montant_paye:'Montant payé (DA)',personne_id:'Profil associé',billet:'Billet à importer',passager_nom:'Nom du passager',passager_prenom:'Prénom du passager',compagnie:'Compagnie',num_vol_aller:'N° du vol aller',num_vol_retour:'N° du vol retour',aeroport_depart:'Aéroport de départ',aeroport_arrivee:'Aéroport d’arrivée',aeroport_depart_retour:'Départ du retour',aeroport_arrivee_retour:'Arrivée du retour',date_retour:'Départ du retour — date et heure',date_arrivee_retour:'Arrivée du retour — date et heure',prix:'Montant (DA)',classe:'Classe'};
 function organizeForms(){
  let index=0;
  for(const modal of document.querySelectorAll('.modal')){
   modal.classList.add('ea-polished');
   for(const input of modal.querySelectorAll('.modal-body input:not([type=hidden]):not([type=checkbox]):not([type=radio]),.modal-body select,.modal-body textarea')){
    if(input.closest('.id-scan-panel')||input.id==='reservationOccupantSearch')continue;
    let label=input.previousElementSibling?.matches('label')?input.previousElementSibling:null;
    if(!label){label=document.createElement('label');label.className='form-label';label.textContent=labels[input.name]||input.placeholder||input.name?.replaceAll('_',' ')||'Champ';input.before(label);}
    if(input.type==='date'&&/date_(arrivee|depart)/.test(input.name))label.textContent=input.name==='date_arrivee'?'Date d’arrivée':'Date de départ';
    input.id=input.id||'ea-field-'+(++index);label.htmlFor=input.id;
    if(input.required)label.classList.add('ea-required');
   }
  }
 }
 function initOccupants(){
  const form=document.getElementById('formReservation'),modal=document.getElementById('modalReservation'),input=document.getElementById('reservationOccupantSearch'),list=document.getElementById('reservationOccupantSuggestions'),chips=document.getElementById('reservationOccupantChips'),status=document.getElementById('reservationOccupantStatus');
  if(!form||!input)return;
  const selected=new Map();let timer,sequence=0,active=-1;
  const capacity=()=>Number(form.elements.capacite_max.value)||({single:1,double:2,triple:3,suite:2,appartement:4}[form.elements.type_chambre.value]||1);
  const kind=p=>({equipe:'Équipe',intervenants:'Intervenant',exposant:'Exposant',invite_vip:'Invité VIP',invite_normal:'Participant',autre:'Participant'}[p.source==='personnes'?p.type:p.source]||'Participant');
  function close(){list.classList.add('d-none');input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;}
  function renderChips(){
   chips.replaceChildren();
   for(const [key,p] of selected){
    const chip=document.createElement('span');chip.className='occupant-chip';const text=document.createElement('span');text.textContent=p.nom+' '+p.prenom;chip.append(text);
    const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Retirer '+text.textContent);remove.disabled=isViewer();remove.onclick=()=>{selected.delete(key);renderChips();input.focus();};chip.append(remove);chips.append(chip);
   }
   status.textContent=selected.size?`${selected.size} / ${capacity()} occupant(s) sélectionné(s)`:'Participants, exposants, équipe et intervenants de cet événement.';
   status.classList.toggle('text-danger',selected.size>capacity());
  }
  function choose(p){
   if(isViewer())return;
   if(selected.size>=capacity()){status.textContent='Capacité maximale atteinte. Retirez un occupant ou augmentez la capacité.';status.classList.add('text-danger');return;}
   selected.set(p.key,p);renderChips();input.value='';sequence++;close();input.focus();
  }
  async function search(){
   const q=input.value.trim(),seq=++sequence,eventId=currentEventId;
   if(!q){close();return;}
   status.textContent='Recherche…';
   try{
    const rows=await apiFetch(`/reservations/event/${eventId}/candidates?q=${encodeURIComponent(q)}`);
    if(seq!==sequence||eventId!==currentEventId)return;
    list.replaceChildren();active=-1;
    const available=rows.filter(p=>!selected.has(p.key));
    for(const p of available){
     const option=document.createElement('button');option.type='button';option.className='occupant-option';option.id='occupant-option-'+seq+'-'+list.children.length;option.setAttribute('role','option');option.setAttribute('aria-selected','false');
     const name=document.createElement('span');name.textContent=p.nom+' '+p.prenom;const type=document.createElement('small');type.textContent=kind(p);option.append(name,type);option.onclick=()=>choose(p);list.append(option);
    }
    if(!available.length){const empty=document.createElement('div');empty.className='occupant-empty';empty.textContent='Aucune personne correspondante.';list.append(empty);}
    list.classList.remove('d-none');input.setAttribute('aria-expanded','true');status.textContent=available.length+' proposition(s)';
   }catch(err){if(seq===sequence){close();status.textContent=err.message||'Recherche indisponible';}}
  }
  input.addEventListener('input',()=>{sequence++;clearTimeout(timer);close();timer=setTimeout(search,220);});
  input.addEventListener('focus',()=>{if(input.value.trim())search();});
  input.addEventListener('keydown',e=>{
   const options=[...list.querySelectorAll('[role=option]')];
   if(e.key==='Escape'){close();return;}
   if(['ArrowDown','ArrowUp'].includes(e.key)&&options.length&&!list.classList.contains('d-none')){
    e.preventDefault();active=active<0?(e.key==='ArrowDown'?0:options.length-1):(active+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;
    options.forEach((o,i)=>{o.classList.toggle('active',i===active);o.setAttribute('aria-selected',i===active?'true':'false');});
    input.setAttribute('aria-activedescendant',options[active].id);options[active].scrollIntoView({block:'nearest'});
   }
   if(e.key==='Enter'){e.preventDefault();if(active>=0&&!list.classList.contains('d-none'))options[active]?.click();else if(input.value.trim())status.textContent='Sélectionnez une personne dans les propositions.';}
  });
  document.addEventListener('click',e=>{if(!e.target.closest('.occupant-picker'))close();});
  for(const name of ['capacite_max','type_chambre'])form.elements[name].addEventListener('change',renderChips);
  form.addEventListener('reset',()=>{selected.clear();input.value='';sequence++;clearTimeout(timer);close();queueMicrotask(renderChips);});
  modal.addEventListener('show.bs.modal',e=>{if(reservationSaving){e.preventDefault();return;}form.reset();resetReservationMode();input.disabled=isViewer();});
  modal.addEventListener('hidden.bs.modal',()=>{sequence++;clearTimeout(timer);close();resetReservationMode();});
  // Only registered, selected identities are submitted; never arbitrary typed names.
  window.ReservationOccupants={values:()=>[...selected.keys()],set:rows=>{selected.clear();for(const p of rows)selected.set(p.key,p);input.value='';sequence++;close();renderChips();}};
 }
 function initProgramme(){
  const form=document.getElementById('formProgramme'),modal=document.getElementById('modalProgramme'),select=document.getElementById('programmeIntervenantSelect'),status=document.getElementById('programmeIntervenantStatus');
  if(!form||!select)return;
  let speakers=new Map(),loading=false,generation=0;
  function fillSpeaker(){const person=speakers.get(select.value);for(const field of ['nom','prenom','poste','email'])form.elements['intervenant_'+field].value=person?.[field]||'';}
  select.addEventListener('change',fillSpeaker);
  modal.addEventListener('show.bs.modal',async()=>{
   const seq=++generation;loading=true;select.disabled=true;speakers.clear();select.replaceChildren(new Option('Chargement…',''));status.textContent='';
   try{
    const rows=await apiFetch(`/intervenants/event/${currentEventId}`);if(seq!==generation)return;
    select.replaceChildren(new Option('Sans intervenant',''));
    for(const p of rows){speakers.set(String(p.id),p);select.add(new Option(`${p.nom} ${p.prenom}${p.poste?' — '+p.poste:''}`,p.id));}
    status.textContent=rows.length?'Profils de la rubrique Intervenants.':'Aucun intervenant enregistré pour cet événement.';
   }catch(err){if(seq===generation){select.replaceChildren(new Option('Liste indisponible',''));status.textContent=err.message;}}
   finally{if(seq===generation){loading=false;select.disabled=isViewer();fillSpeaker();}}
  });
  modal.addEventListener('hidden.bs.modal',()=>{generation++;loading=false;});
  form.addEventListener('submit',async e=>{
   e.preventDefault();if(isViewer())return;if(loading){toast('Chargement des intervenants…','warning');return;}
   if(select.value&&!speakers.has(select.value)){toast('Choisissez un intervenant existant.','warning');return;}
   fillSpeaker();const fd=new FormData(form);fd.set('event_id',currentEventId);const save=form.querySelector('[type=submit]');if(save.disabled)return;save.disabled=true;
   try{await apiFetch('/programmes',{method:'POST',body:fd});toast('Créneau ajouté');bootstrap.Modal.getInstance(modal)?.hide();form.reset();loadProgrammes();}
   catch(err){toast(err.message,'danger');}
   finally{save.disabled=isViewer();}
  });
 }
 document.addEventListener('DOMContentLoaded',()=>{organizeForms();initOccupants();initProgramme();});
})();

;

