/* stand-plan-view.js */
/* Shared grid renderer: no HTML injection from company names. */
(function(root){
 const address=slot=>String.fromCharCode(65+slot%4)+(Math.floor(slot/4)+1);
 const normalize=text=>String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 function render(container,stands,{editable=false,selected=null,onSelect=()=>{},onMove=()=>{},query='',extraRow=false}={}){
  const left=container.querySelector('.stand-map-scroll')?.scrollLeft||0,top=container.querySelector('.stand-map-scroll')?.scrollTop||0;
  container.replaceChildren();container.classList.add('stand-view');
  const toolbar=document.createElement('div');toolbar.className='plan-view-toolbar';const legend=document.createElement('span');legend.textContent=`${stands.length} stand(s) · 4 colonnes`;toolbar.append(legend);
  const toggle=document.createElement('button');toggle.type='button';toggle.className='plan-view-toggle';toggle.textContent=container.classList.contains('is-list')?'Vue plan':'Vue liste';toggle.setAttribute('aria-pressed',String(container.classList.contains('is-list')));toggle.onclick=()=>{const list=container.classList.toggle('is-list');toggle.textContent=list?'Vue plan':'Vue liste';toggle.setAttribute('aria-pressed',String(list));};toolbar.append(toggle);container.append(toolbar);
  const matches=p=>!query||normalize(p.company+' '+p.numero+' '+address(p.slot)).includes(normalize(query));
  const scroll=document.createElement('div');scroll.className='stand-map-scroll';scroll.tabIndex=0;scroll.setAttribute('aria-label','Plan des stands, défilement horizontal possible');
  const grid=document.createElement('div');grid.className='stand-map-grid';const last=Math.max(0,...stands.map(s=>s.slot)),count=Math.max(4,Math.ceil((last+1)/4)*4)+(extraRow?4:0),bySlot=new Map(stands.map(p=>[p.slot,p]));
  for(let slot=0;slot<Math.min(count,1000);slot++){
   const p=bySlot.get(slot),tile=document.createElement(editable||p?'button':'div');tile.className='stand-tile'+(p?' occupied':' empty');tile.dataset.slot=String(slot);if(tile.tagName==='BUTTON')tile.type='button';
   const pos=document.createElement('small');pos.className='stand-position';pos.textContent=address(slot)+(p?' · '+p.numero:'');tile.append(pos);
   const name=document.createElement('strong');name.textContent=p?p.company:(editable?'Emplacement libre':'');tile.append(name);
   if(p){tile.dataset.standId=String(p.id);tile.style.setProperty('--stand-accent',['#3378aa','#268c80','#7c70b4','#a58143'][p.id%4]);tile.setAttribute('aria-label',p.company+', emplacement '+address(slot)+', stand '+p.numero);if(!matches(p))tile.classList.add('not-matching');if(p.id===selected){tile.classList.add('selected');tile.setAttribute('aria-pressed','true');}tile.onclick=()=>onSelect(p);
    if(editable){tile.draggable=true;tile.addEventListener('dragstart',e=>{e.dataTransfer.setData('application/x-event-stand',String(p.id));e.dataTransfer.effectAllowed='move';});}
   }else if(editable){tile.setAttribute('aria-label','Emplacement '+address(slot));tile.onclick=()=>onMove(selected,slot);}
   if(editable){tile.addEventListener('dragover',e=>{e.preventDefault();tile.classList.add('drop-target');});tile.addEventListener('dragleave',()=>tile.classList.remove('drop-target'));tile.addEventListener('drop',e=>{e.preventDefault();tile.classList.remove('drop-target');onMove(Number(e.dataTransfer.getData('application/x-event-stand')),slot);});}
   grid.append(tile);
  }
  scroll.append(grid);container.append(scroll);
  const help=document.createElement('p');help.className='plan-pan-hint';help.textContent='Sur petit écran : faites glisser le plan ou utilisez la vue liste.';container.append(help);
  const list=document.createElement('div');list.className='stand-company-list';
  for(const p of stands.filter(matches)){const row=document.createElement('button');row.type='button';row.className='stand-list-row';const title=document.createElement('strong');title.textContent=p.company;const label=document.createElement('span');label.textContent=address(p.slot)+' · '+p.numero;row.append(title,label);row.onclick=()=>{onSelect(p);container.classList.remove('is-list');toggle.textContent='Vue liste';toggle.setAttribute('aria-pressed','false');container.querySelector(`[data-stand-id="${p.id}"]`)?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'});};list.append(row);}
  if(!stands.length){const empty=document.createElement('p');empty.className='plan-no-stands';empty.textContent='Les stands apparaîtront ici dès l’ajout des exposants.';container.prepend(empty);}
  if(query&&!stands.some(matches)){const empty=document.createElement('p');empty.className='plan-no-stands';empty.textContent='Aucune société ne correspond à votre recherche.';list.append(empty);}
  container.append(list);scroll.scrollLeft=left;scroll.scrollTop=top;return container;
 }
 root.StandGrid={render,address};
})(window);

;

/* stand-plan-admin.js */
(function(){
 let data=null,selected=null,busy=false,generation=0,eventId=null,modal,grid,status;
 const canWrite=()=>!isViewer()&&(isPrivilegedRole(currentUser?.role)||currentUser?.permissions?.all||currentUser?.permissions?.exposants||currentUser?.permissions?.stands);
 function message(text,error=false){status.textContent=text;status.classList.toggle('text-danger',error);}
 function shareState(){
  const enabled=!!data?.share?.enabled,url=data?.share?.url?new URL(data.share.url,location.origin).href:'';
  document.getElementById('standShareUrl').value=enabled?url:'';
  document.getElementById('standShareActivate').hidden=enabled;
  document.getElementById('standShareDisable').hidden=!enabled;
  for(const id of ['standShareCopy','standShareOpen'])document.getElementById(id).classList.toggle('d-none',!enabled);
  const open=document.getElementById('standShareOpen');if(enabled)open.href=url;else open.removeAttribute('href');
  modal.querySelectorAll('[data-plan-write]').forEach(el=>el.classList.toggle('d-none',!canWrite()));
 }
 function draw(){
  if(!data)return;shareState();
  const stand=data.stands.find(p=>p.id===selected);document.getElementById('standSelectedLabel').textContent=stand?stand.company+' · '+StandGrid.address(stand.slot):'Sélectionnez un stand';
  if(stand)document.getElementById('standTargetSlot').value=stand.slot+1;
  StandGrid.render(grid,data.stands,{editable:canWrite()&&!busy,selected,extraRow:canWrite(),onSelect:p=>{selected=p.id;draw();},onMove:move});
 }
 async function load(){
  const seq=++generation;message('Chargement du plan…');
  try{const result=await apiFetch(`/stand-plans/event/${eventId}`);if(seq!==generation)return;data=result;draw();message(data.stands.length+' stand(s) · '+(canWrite()?'Les modifications sont enregistrées automatiquement.':'Vue en lecture seule.'));}
  catch(e){if(seq===generation)message(e.message,true);}
 }
 async function move(id,slot){
  if(!canWrite()||busy)return;
  if(!id){message('Sélectionnez d’abord un stand.',true);return;}
  if(!Number.isInteger(slot)||slot<0||slot>999){message('Choisissez une position entre 1 et 1 000.',true);return;}
  const stand=data.stands.find(p=>p.id===id),other=data.stands.find(p=>p.slot===slot&&p.id!==id);
  if(!stand||stand.slot===slot)return;
  if(other&&!confirm(`Échanger les emplacements de « ${stand.company} » et « ${other.company} » ?`))return;
  busy=true;message('Enregistrement…');modal.querySelectorAll('.plan-move-controls button').forEach(b=>b.disabled=true);
  try{await apiFetch(`/stand-plans/event/${eventId}/position`,{method:'PUT',body:{stand_id:id,slot}});selected=id;await load();message('Emplacement enregistré. Le lien partagé se met à jour automatiquement.');}
  catch(e){message(e.message,true);}
  finally{busy=false;modal.querySelectorAll('.plan-move-controls button').forEach(b=>b.disabled=false);draw();}
 }
 window.openStandPlan=function(){
  if(!currentEventId){toast('Sélectionnez un événement.','warning');return;}
  eventId=currentEventId;selected=null;data=null;grid.replaceChildren();bootstrap.Modal.getOrCreateInstance(modal).show();load();
 };
 document.addEventListener('DOMContentLoaded',()=>{
  modal=document.getElementById('modalStandPlan');grid=document.getElementById('standAdminGrid');status=document.getElementById('standAdminStatus');if(!modal)return;
  modal.addEventListener('hidden.bs.modal',()=>{generation++;});
  document.getElementById('standMoveButton').onclick=()=>move(selected,Number(document.getElementById('standTargetSlot').value)-1);
  modal.querySelectorAll('[data-plan-direction]').forEach(b=>b.onclick=()=>{const s=data?.stands.find(p=>p.id===selected);if(s)move(s.id,s.slot+Number(b.dataset.planDirection));else message('Sélectionnez un stand.',true);});
  async function share(method){
   if(!canWrite()||busy)return;if(method==='DELETE'&&!confirm('Désactiver le lien partagé ?'))return;
   busy=true;try{await apiFetch(`/stand-plans/event/${eventId}/share`,{method});await load();message(method==='POST'?'Lien activé. Vous pouvez le copier et le partager.':'Lien désactivé.');}catch(e){message(e.message,true);}finally{busy=false;draw();}
  }
  document.getElementById('standShareActivate').onclick=()=>share('POST');document.getElementById('standShareDisable').onclick=()=>share('DELETE');
  document.getElementById('standShareCopy').onclick=async()=>{const input=document.getElementById('standShareUrl');try{await navigator.clipboard.writeText(input.value);message('Lien copié.');}catch{input.focus();input.select();message('Copiez le lien sélectionné.');}};
 });
})();

